        internal int GetPageRotation(PdfDictionary page) {
            PdfNumber rotate = (PdfNumber)GetPdfObject(page.Get(PdfName.ROTATE));
            if (rotate == null)
                return 0;
            else {
                int n = rotate.IntValue;
                n %= 360;
                return n < 0 ? n + 360 : n;
            }
        }
