        protected internal void ReadDocObjPartial() {
            xrefObj = 
// MASC 20070308. CF compatibility patch
#if !NETCF
				ArrayList.Repeat(
#else
				ArrayListEx.Repeat(
#endif
					null, xref.Length / 2
				);
            ReadDecryptedDocObj();
            if (objStmToOffset != null) {
                int[] keys = objStmToOffset.GetKeys();
                for (int k = 0; k < keys.Length; ++k) {
                    int n = keys[k];
                    objStmToOffset[n] = xref[n * 2];
