class Expr(Expression):
  """
    The ``Expr`` object with helpers for sub-classes. It also derives
    from ``ast.expr.Expression``.
  """
  UNKNOWN = 1
  CONSTANT = 2
  REFERENCE = 3
  OPERATOR = 4
  COMPARATOR = 5
  UNDEFINED = 6

  CAST_TYPE_BOOLEAN = 1
  CAST_TYPE_INTEGER = 2
  CAST_TYPE_NUMBER = 3
  CAST_TYPE_STRING = 4
  CAST_TYPE_UNKNOWN = 5

  def __init__(self, kind=UNKNOWN, data=None, terminal=False, binary=False):
    Expression.__init__(self)
    self._kind = kind
    self._data = data
    self._ast = None
    self._terminal = terminal
    self._binary = binary
    self._cast_type = Expr.CAST_TYPE_UNKNOWN

  @property
  def kind(self):
    return self._kind

  @kind.setter
  def kind(self, value):
    self._kind = value

  @property
  def data(self):
    return self._data

  @data.setter
  def data(self, value):
    self._data = value

  @property
  def ast(self):
    return self._ast

  @ast.setter
  def ast(self, value):
    self._ast = value

  @property
  def cast_type(self):
    return self._cast_type

  @cast_type.setter
  def cast_type(self, value):
    self._cast_type = value

  @property
  def terminal(self):
    return self._terminal

  @terminal.setter
  def terminal(self, value):
    self._terminal = value

  @property
  def binary(self):
    return self._binary

  @binary.setter
  def binary(self, value):
    self._binary = value

  def __ne__(self, obj):
    return True

  def __eq__(self, obj):
    return False

