public class CheckBoxPreferenceHideScore extends CustomCheckBoxPreference {

    public CheckBoxPreferenceHideScore(Context context, AttributeSet attrs, int defStyleAttr) {
        super(context, attrs, defStyleAttr);
    }

    @TargetApi(Build.VERSION_CODES.LOLLIPOP)
    public CheckBoxPreferenceHideScore(Context context, AttributeSet attrs, int defStyleAttr, int defStyleRes) {
        super(context, attrs, defStyleAttr, defStyleRes);
    }

    public CheckBoxPreferenceHideScore(Context context, AttributeSet attrs) {
        super(context, attrs);
    }

    public CheckBoxPreferenceHideScore(Context context) {
        super(context);
    }

    @Override
    protected void onClick() {
        boolean value = !isChecked();
        prefs.putHideScore(value);
        setChecked(value);
    }

    public void update() {
        setChecked(prefs.getSavedHideScore());
    }
}
app/src/main/java/de/tobiasbielefeld/solitaire/LoadGame.java
public class LoadGame {

    private String gameName;
    private String sharedPrefName;
    private ArrayList<AllGameInformation> allGameInformation = new ArrayList<>();
    private int GAME_COUNT;

    /**
     * load the game class and set the shown name and the name used for the sharedPref of the
     * current game.
     *
     * @param activity The activity to get the strings from the xml file
     * @param index    The index of the game to start
     */
    public Game loadClass(AppCompatActivity activity, int index) {

        sharedPrefName = allGameInformation.get(index).getSharedPrefName();
        gameName = allGameInformation.get(index).getName(activity.getResources());

        switch (index) {
            default:
                Log.e("LoadGame.loadClass()", "Your games seems not to be added here?");//fallthrough
            case 0:
                return new AcesUp();
            case 1:
                return new Calculation();
            case 2:
                return new Canfield();
            case 3:
