    public Board[] newArray(int size) {
      return new Board[size];
    }
  };

  @Override
  public void readExternal(ObjectInput in) throws IOException, ClassNotFoundException {
    if (in.readBoolean()) {
      boardType = BoardType.values()[in.readShort()];
    }
    if (in.readBoolean()) {
      boardID = in.readUTF();
    }
    if (in.readBoolean()) {
      boardEngName = in.readUTF();
