	 */
	public SearchQuery thisPhrase(String thisPhrase) {
		if( alreadySetQuery ) {
			log.warning( "SearchQuery string already set, overriding with compound query");
		} // if
		alreadySetQuery = true;

		this.thisPhrase = thisPhrase;
