			refreshMenu = (ActionMenuView) v.findViewById(R.id.refresh_menu);
			menuInflater.inflate(R.menu.menu_refresh, refreshMenu.getMenu());
		}

	}

	static class ItemHolder extends RecyclerView.ViewHolder {

		final View rowLayout;
