public final class Property {

	public int image;
	public String text;
	public View.OnClickListener clickListener;

	public Property() {}

	public Property(int image, String text, View.OnClickListener clickListener) {
		this.image = image;
		this.text = text;
		this.clickListener = clickListener;
	}

	static class PropertyHolder extends RecyclerView.ViewHolder {

		final View view;
		final ImageView propertyImage;
		final TextView propertyText;
		final int staticBackground;
		final int selectableBackground;
		Drawable selectableBackgroundDrawable;
		Property property;

		private PropertyHolder(View v, int staticBackgroundResId, int selectableBackgroundResId) {
			super(v);
			view = v;
			propertyImage = (ImageView) v.findViewById(R.id.property_image);
			propertyText = (TextView) v.findViewById(R.id.property_text);
			staticBackground = staticBackgroundResId;
			selectableBackground = selectableBackgroundResId;
		}

		public static PropertyHolder build(ViewGroup parent) {
			return build(parent, 0, 0);
		}

		public static PropertyHolder build(ViewGroup parent, int staticBackgroundResId) {
			return build(parent, staticBackgroundResId, 0);
		}

		public static PropertyHolder build(ViewGroup parent, int staticBackgroundResId, int selectableBackgroundResId) {
			return new PropertyHolder(LayoutInflater.from(parent.getContext()).inflate(R.layout.list_item_property, parent, false),
					staticBackgroundResId, selectableBackgroundResId);
		}

		public void bind(Property property) {
			this.property = property;
			propertyImage.setImageResource(property.image);
			propertyText.setText(property.text);
			if (property.clickListener == null) {
				// Remove touch feedback
				view.setOnClickListener(null);
				view.setClickable(false);
				view.setFocusable(false);
				view.setBackgroundResource(staticBackground);
			} else {
				view.setOnClickListener(this.property.clickListener);
				view.setClickable(true);
				view.setFocusable(true);
				if (selectableBackground > 0) {
					view.setBackgroundResource(selectableBackground);
				} else {
					// Set a selectable ripple drawable background
					if (selectableBackgroundDrawable == null) {
						int[] attrs = new int[]{android.R.attr.selectableItemBackground};
						TypedArray ta = view.getContext().obtainStyledAttributes(attrs);
						selectableBackgroundDrawable = ta.getDrawable(0);
						ta.recycle();
					}
					view.setBackgroundDrawable(selectableBackgroundDrawable.getConstantState().newDrawable().mutate());
				}
			}
		}
	}

}
app/src/main/java/com/ratebeer/android/gui/services/SyncService.java
public final class SyncService extends IntentService {

	private static final BehaviorSubject<Boolean> SYNC_STATUS = BehaviorSubject.create(false);
	private static final int NOTIFY_SYNC = 0;
	private static final int REQUEST_SYNC = 0;

	public static Intent start(Context context) {
		return new Intent(context, SyncService.class);
	}

	public static Observable<Boolean> getSyncStatus() {
		return SYNC_STATUS.asObservable();
	}

	public SyncService() {
		super("RateBeer SyncService");
	}

	@Override
	protected void onHandleIntent(Intent intent) {

		if (SYNC_STATUS.toBlocking().first()) {
			return; // Already syncing

		}

		// Perform sync by loading and then storing all of the user's ratings
		final AtomicInteger i = new AtomicInteger();
		Db.syncRatings(this, progress -> reportProgress(true, null, progress))
				.toBlocking()
				.subscribe(
						r -> RBLog.d("R:" + i.getAndIncrement()),
						e -> reportProgress(false, e, null),
						() -> reportProgress(false, null, 100F));

	}

	private void reportProgress(boolean isActive, Throwable error, Float progress) {

		NotificationManager notificationManager = (NotificationManager) getSystemService(NOTIFICATION_SERVICE);

		// Broadcast sync status for external listeners
		SYNC_STATUS.onNext(isActive);

		// Remove persistent notification when done
		if (!isActive && error == null) {
			notificationManager.cancel(NOTIFY_SYNC);
			return;
		}

		// Show error (and allow retry) when sync failed
		if (error != null) {
			PendingIntent retryIntent = PendingIntent.getService(this, REQUEST_SYNC, start(this), PendingIntent.FLAG_CANCEL_CURRENT);
			notificationManager
					.notify(NOTIFY_SYNC, new NotificationCompat.Builder(this)
							.setPriority(NotificationCompat.PRIORITY_DEFAULT)
							.setCategory(NotificationCompat.CATEGORY_ERROR)
							.setAutoCancel(true)
							.setSmallIcon(R.drawable.ic_stat_error)
							.setContentTitle(getString(R.string.sync_error))
							.setContentText(getString(R.string.sync_tryagain))
							.setContentIntent(retryIntent)
					.build());
			return;
		}

		// Show ongoing sync progress
		notificationManager.notify(NOTIFY_SYNC,
				new NotificationCompat.Builder(this)
						.setPriority(NotificationCompat.PRIORITY_LOW)
						.setCategory(NotificationCompat.CATEGORY_SERVICE)
						.setOngoing(true)
						.setSmallIcon(R.drawable.ic_stat_default)
						.setProgress(100, progress.intValue(), false)
						.setContentTitle(getString(R.string.sync_insync))
						.build());

	}

}
app/src/main/java/com/ratebeer/android/gui/lists/SearchSuggestion.java
public final class SearchSuggestion {

	public static final int TYPE_HISTORY = 0;
	public static final int TYPE_BEER = 1;
	public static final int TYPE_RATING = 2;
	public static final int TYPE_BREWERY = 3;
	public static final int TYPE_PLACE = 4;

	public int type;
	public Long itemId;
	public String suggestion;

	private SearchSuggestion() {}

	public static SearchSuggestion fromHistoricSearch(HistoricSearch historicSearch) {
		SearchSuggestion suggestion = new SearchSuggestion();
		// NOTE No item id attached
		suggestion.type = TYPE_HISTORY;
		suggestion.suggestion = historicSearch.name;
		return suggestion;
	}

	public static SearchSuggestion fromBeer(Beer beer) {
		SearchSuggestion suggestion = new SearchSuggestion();
		suggestion.type = TYPE_BEER;
		suggestion.itemId = beer._id;
		suggestion.suggestion = beer.name;
		return suggestion;
	}

	public static SearchSuggestion fromRating(Rating rating) {
		SearchSuggestion suggestion = new SearchSuggestion();
		suggestion.type = TYPE_RATING;
		suggestion.itemId = rating.beerId;
		suggestion.suggestion = rating.beerName;
		return suggestion;
	}

	public static SearchSuggestion fromBrewery(Brewery brewery) {
		SearchSuggestion suggestion = new SearchSuggestion();
		suggestion.type = TYPE_BREWERY;
		suggestion.itemId = brewery._id;
		suggestion.suggestion = brewery.name;
		return suggestion;
	}

	public static SearchSuggestion fromPlace(Place place) {
		SearchSuggestion suggestion = new SearchSuggestion();
		suggestion.type = TYPE_PLACE;
		suggestion.itemId = place._id;
		suggestion.suggestion = place.name;
		return suggestion;
	}

	public String uniqueCode() {
		// A search suggestion is unique per type (but beers and ratings are not) and per id (or suggestion text if no id is available)
		return (type == TYPE_BEER? TYPE_RATING: type) + (itemId != null? Long.toString(itemId): suggestion);
	}

}
