    FIBS_MATCHOVER,

    ACCEPT_DOUBLE,
    ACCEPT_RESIGN,
    GET_RESIGN_VALUE,
    ASK_FOR_DOUBLING,
    ASK_FOR_RESIGNATION,
    EVALUATE_BEST_MOVE,
    INITIALIZE_ENVIRONMENT,
    ROLL_DICE,
    DICES_ROLLED,
    SET_BOARD,
    SET_GAME_TURN,
