      @Override
      public void run() {
        if (fsm != GnuBackgammon.fsm)
          return;
        GnubgAPI.SetBoard(b1, b2);
        int resign = 1;
        while (GnubgAPI.AcceptResign(resign) != resign)
          resign++;

        final int r = resign;

        Gdx.app.postRunnable(new Runnable() {
          @Override
          public void run() {
            if (fsm == GnuBackgammon.fsm)
              GnuBackgammon.fsm.processEvent(GameFSM.Events.GET_RESIGN_VALUE, r);
