						System.out.println("Found Storm classes (http://nathanmarz.github.io) on the classpath, " +
								"which introduce threading/synchronization issues. Leaving Logger unconfigured!");
						isStorm = true;
					} catch (Exception e) { /*swallow*/ }

					if(!isStorm) {
