		if(str == null)
			return null;
		if(maxLength <= 0)
			return "";
		if(str.length() <= maxLength)
			return str;
		return str.substring(0, maxLength) + " ... [trimmed " + 
			(str.length() - maxLength) + " chars]";
	}

