		}
		int index = (int)((double)list.size() * Math.random());
		return list.get(index);
	}

	public String join(List<?> list) {
		return join(list, "\n");
	}
	public String join(List<?> list, String delimiter) {
		StringBuilder b = new StringBuilder();
		int counter = 0;
		for(Object o : list) {
			b.append("" + o);
			if(++counter < list.size()) {
				b.append(delimiter);
			}
		}
		return b.toString();
	}
