def show(self, with_trans=False):
    tr, re = '', ''
    if self.is_transparent():
        # TODO: eval the best convinience here
        if not with_trans:
            return ''
        tr = ' - transparent'
    else:
        tr = ''
    if self.ReprName != '':
        re = ''.join((self.ReprName, ' '))
    return '<%s[%s%s] : %s>' % ( re, self.CallName, tr, repr(self) )
