     */
    public void setHomePointPosition(int position) {
        mEditor.putInt(HOME_POINT, position);
        mEditor.commit();
    }

    public int getHomePointPosition() {
        try {
            return mSharedPreferences.getInt(HOME_POINT, LEFT);
        } catch (Exception e) {
            return LEFT;
        }
    }


    /**
